// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  frame,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

test('D1 - Ball bounces off bricks', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = 100;
  state.ball.vx = 0;
  step(state, 0.01);
  assert.strictEqual(state.ball.vy, -100, 'Ball should bounce UP after hitting top face');
});

test('D2 - Ball is repositioned after brick collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 2; 
  state.ball.vy = 100;
  step(state, 0.01);
  assert.ok(state.ball.y <= brick.y - state.ball.r || state.ball.y >= brick.y + brick.h + state.ball.r, 'Ball should be pushed out of the brick');
});

test('D3 - Corner hit flips both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - state.ball.r + 1;
  state.ball.y = brick.y - state.ball.r + 1;
  state.ball.vx = 100;
  state.ball.vy = 100;
  step(state, 0.01);
  assert.strictEqual(state.ball.vx, -100, 'vx should flip');
  assert.strictEqual(state.ball.vy, -100, 'vy should flip');
});

test('D4 - No double inversion on seams', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];
  state.ball.x = b1.x + b1.w - 1;
  state.ball.y = b1.y + b1.h / 2;
  state.ball.vx = 100;
  step(state, 0.01);
  assert.strictEqual(state.ball.vx, -100, 'vx should be -100, not 100');
});

test('D5 - No tunneling at high speed', () => {
  const state = createState(6);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10;
  state.ball.vy = 710; 
  // In one frame (dt=0.05), ball moves 35.5px. 
  // y becomes brick.y - 10 + 710 * 0.05 = brick.y + 25.5 (passed through the 20px brick).
  // But it should have collided.
  step(state, 0.05);
  assert.strictEqual(state.ball.vy, -710, 'Ball should have bounced despite jumping over brick');
});

